/**
 * Sync generated site content from repo sources of truth. Runs before every
 * `astro dev` / `astro build` (see package.json scripts), so the published
 * pages can never drift from the files they mirror:
 *
 *   docs/decisions/*.md            -> src/content/docs/reference/decisions/
 *   taxonomy/milestone_definitions.yaml -> src/content/docs/reference/milestone-taxonomy.md
 *
 * Output paths are gitignored (site/.gitignore). Edit the sources, not the
 * output. docs/validation/ is intentionally untouched here: those artifacts
 * are generated by `pnpm validation:artifacts` and stay in the repository.
 */
import { mkdirSync, readdirSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";
import { parse } from "yaml";

const siteDir = resolve(dirname(fileURLToPath(import.meta.url)), "..");
const repoRoot = resolve(siteDir, "..");
const outDir = join(siteDir, "src/content/docs/reference");

// --- ADRs -------------------------------------------------------------------

const decisionsSrc = join(repoRoot, "docs/decisions");
const decisionsOut = join(outDir, "decisions");
rmSync(decisionsOut, { recursive: true, force: true });
mkdirSync(decisionsOut, { recursive: true });

const adrFiles = readdirSync(decisionsSrc)
  .filter((f) => f.endsWith(".md"))
  .sort();

for (const file of adrFiles) {
  const raw = readFileSync(join(decisionsSrc, file), "utf8");
  const match = raw.match(/^# (.+)\n/);
  if (!match) {
    throw new Error(`${file}: expected a leading H1 to hoist into frontmatter`);
  }
  const title = match[1].replaceAll('"', '\\"');
  const body = raw.slice(match[0].length).trimStart();
  const page = `---\ntitle: "${title}"\n---\n\n${body}`;
  writeFileSync(join(decisionsOut, file), page);
}

// --- Milestone taxonomy -----------------------------------------------------

const PHASE_GROUPS = [
  ["startup_spec", "Startup — Specification"],
  ["startup_build", "Startup — Build"],
  ["startup_release", "Startup — Validation & Release"],
  ["conduct", "Conduct"],
  ["closeout", "Closeout"],
];

const taxonomy = parse(readFileSync(join(repoRoot, "taxonomy/milestone_definitions.yaml"), "utf8"));
const milestones = taxonomy.milestones;

const escape = (s) => String(s).replaceAll("|", "\\|");
const sections = PHASE_GROUPS.map(([group, label]) => {
  const rows = milestones
    .filter((m) => m.phase_group === group)
    .sort((a, b) => a.sequence - b.sequence)
    .map((m) => {
      const notes = [
        m.is_repeating ? "repeating" : null,
        m.default_owner_role ? `default owner: ${m.default_owner_role}` : null,
      ]
        .filter(Boolean)
        .join(" · ");
      const deps = (m.depends_on ?? []).map((d) => `\`${d}\``).join(", ");
      return `| \`${m.code}\` | ${escape(m.label)} | ${deps} | ${notes} |`;
    });
  return [
    `## ${label}`,
    "",
    "| Code | Milestone | Depends on | Notes |",
    "| --- | --- | --- | --- |",
    ...rows,
    "",
  ].join("\n");
});

const taxonomyPage = `---
title: Milestone taxonomy
description: The ${milestones.length} governed milestone codes, by phase group, generated from taxonomy/milestone_definitions.yaml
---

<!-- Generated by site/scripts/sync-generated.mjs from taxonomy/milestone_definitions.yaml. Do not edit. -->

Every milestone on a study board comes from this governed list ([ADR-0008](/dmops-core/reference/decisions/0008-governed-milestone-taxonomy/)). Codes are stable identifiers; labels can be re-worded. Studies may mark milestones N/A but may not invent codes outside the taxonomy. Changes to the list are pull requests against \`taxonomy/milestone_definitions.yaml\`, reviewed like code, and applied with \`pnpm db:sync-taxonomy\` — codes are never deleted, only retired.

A **Depends on** entry means the milestone cannot sensibly complete before its dependencies; the board uses it for ordering, not enforcement. **Repeating** milestones (protocol amendments, interim locks) can occur more than once per study, tracked by occurrence number.

${sections.join("\n")}`;

writeFileSync(join(outDir, "milestone-taxonomy.md"), taxonomyPage);

console.log(
  `[sync-generated] wrote ${adrFiles.length} ADRs and milestone-taxonomy.md (${milestones.length} codes)`,
);
